/* Chapter 1: field-collected regression with held-out target validation. */
const ExoCalibration=(()=>{
 const tower={x:3000,y:1900},stations=[.2,.35,.5,.65,.8,.95].map((x,i)=>({id:i,x:3000,y:1900+x*1000,distance:x,test:i>=4,name:i<4?'试射点 '+(i+1):'测试点 '+(i-3)}));
 function fresh(){return {active:false,rows:[],w:.15,b:.1,power:.35,autoAim:false,steps:0,checks:[],unlocked:false,shots:0,beam:null,message:'先到试射点 1，调整功率并开火。靶标会告诉你，这个距离需要多大的功率。'}}
 function loss(s){return s.rows.length?s.rows.reduce((a,p)=>a+(s.w*p.x+s.b-p.y)**2,0)/s.rows.length:null}
 function nearest(u){return stations.slice().sort((a,b)=>Math.hypot(a.x-u.x,a.y-u.y)-Math.hypot(b.x-u.x,b.y-u.y))[0]}
 function set(s,key,value){if(!['w','b','power'].includes(key)||!Number.isFinite(value))return;s[key]=Math.max(key==='w'?0:0,Math.min(key==='w'?1.2:1,value));if(key!=='power')s.checks=[]}
 function shoot(s,u){if(!s.active)return false;const pad=nearest(u);if(Math.hypot(pad.x-u.x,pad.y-u.y)>65){s.message='先驶入发光的试射点，再开火。';return false}if(pad.test&&s.rows.length<4){s.message='这里用于独立测试，数据不会加入训练。请先完成四个试射点的记录。';return false}const x=pad.distance,required=.62*x+.18+(pad.test?0:Math.sin(pad.id*7+2)*.006),prediction=s.autoAim?s.w*x+s.b:s.power,error=prediction-required;s.shots++;s.beam={from:{x:u.x,y:u.y},to:{x:tower.x+error*400,y:tower.y},error,t:1};if(!pad.test){const row={id:pad.id,x,y:required};s.rows=s.rows.filter(p=>p.id!==pad.id);s.rows.push(row);s.rows.sort((a,b)=>a.x-b.x);s.checks=[];s.message=`${pad.name}：距离 ${Math.round(x*1000)} m，靶标测得所需功率 ${(required*100).toFixed(1)}%。记录 ${s.rows.length}/4。${s.rows.length===4?'打开校准设置，让预测线尽量贴近测量点。':'去下一个试射点继续记录。'}`;}else{if(!s.autoAim){s.message='测试时需要让模型决定功率。请先在校准设置中开启“自动设置功率”，再开火。';return false}const hit=Math.abs(error)<.035;s.checks=s.checks.filter(p=>p.id!==pad.id);s.checks.push({id:pad.id,error,hit});s.message=`${pad.name}：偏差 ${(Math.abs(error)*100).toFixed(1)}%，${hit?'命中':'未命中'}。${hit?'再去另一个测试点试试。':'回到校准设置调整参数，也可以检查之前的试射记录。'}`;if(s.checks.filter(p=>p.hit).length===2){s.unlocked=true;s.message='两个新距离都命中了！自动设置功率已解锁。模型从四次试射中学到了距离和功率的关系，所以也能预测新的距离。'}}return true}
 function train(s,count=1){if(s.rows.length<2)return false;s.checks=[];for(let k=0;k<count;k++){let dw=0,db=0;for(const p of s.rows){const e=s.w*p.x+s.b-p.y;dw+=2*e*p.x/s.rows.length;db+=2*e/s.rows.length}s.w-=.3*dw;s.b-=.3*db;s.steps++}return true}
 function save(s){try{localStorage.setItem('exo-calibration-v1',JSON.stringify({rows:s.rows,w:s.w,b:s.b,steps:s.steps,unlocked:s.unlocked,autoAim:s.autoAim}))}catch{}}
 function restore(){const s=fresh();try{const v=JSON.parse(localStorage.getItem('exo-calibration-v1'));if(v&&Number.isFinite(v.w)&&v.w>=0&&v.w<=1.2&&Number.isFinite(v.b)&&v.b>=0&&v.b<=1&&Array.isArray(v.rows)&&v.rows.length<=4&&v.rows.every(p=>Number.isInteger(p.id)&&p.id>=0&&p.id<4&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x===stations[p.id].distance&&p.y>=0&&p.y<=1)){s.rows=v.rows.filter((p,i,a)=>a.findIndex(q=>q.id===p.id)===i);s.w=v.w;s.b=v.b;s.steps=Number.isFinite(v.steps)?v.steps:0;s.unlocked=v.unlocked===true;s.autoAim=v.autoAim===true}}catch{}return s}
 function panel(s){const l=loss(s);return `<div class="cal-panel"><span class="exo-tag">第 1 课 · 调准发射功率</span><h2>试射几次，教机甲选对功率。</h2><p>四个试射点的记录用于训练；橙色测试点只检查模型在新距离上是否准确。这个练习用简单的线性关系模拟能量传输，不是真实弹道。</p><canvas id="cal-chart" width="560" height="270" aria-label="横轴是距离，纵轴是所需功率。圆点是你的测量记录，青线是模型预测"></canvas><div class="cal-grid"><label>距离对功率的影响 · 斜率 w <input type="range" min="0" max="1.2" step=".01" value="${s.w}" oninput="Exo.calSet('w',+this.value)"></label><label>基础功率 · 截距 b <input type="range" min="0" max="1" step=".01" value="${s.b}" oninput="Exo.calSet('b',+this.value)"></label></div><div id="cal-metrics">试射记录 ${s.rows.length}/4 · MSE ${l===null?'尚无数据':l.toFixed(5)} · 已调整 ${s.steps} 次</div><div class="cal-grid"><button onclick="Exo.calTrain(1)">调整一次 · 梯度下降</button><button onclick="Exo.calTrain(100)">自动校准 100 步</button></div><label><input type="checkbox" ${s.autoAim?'checked':''} onchange="Exo.calAim(this.checked)"> 自动设置功率：按模型预测发射</label><label>手动试射功率 <input type="range" min="0" max="1" step=".01" value="${s.power}" oninput="Exo.calSet('power',+this.value)"></label><p id="cal-dialog-status" role="status"></p><details><summary>想了解背后的原理？</summary><p>试射记录是训练数据；两个滑块控制模型参数。均方误差（MSE）衡量预测值和测量值的差距，越小表示越接近。自动校准使用梯度下降，让参数朝着降低误差的方向调整。只有近距离记录时，远距离预测可能不可靠；测试记录不会用于更新参数。</p><p>现实用途：传感器标定、功耗估计、工业设备校准。线性关系是建模假设，不代表所有系统都遵循直线。</p></details>${s.active?'':'<button onclick="closeModal();Exo.calResume()">继续试射与测试</button>'}<button class="primary" onclick="closeModal()">回到驾驶舱</button><button onclick="closeModal();Exo.calExit()">返回自由探索 · 保留进度</button></div>`}
 function chart(s){const el=document.getElementById('cal-chart');if(!el)return;const g=el.getContext('2d');g.fillStyle='#101f2a';g.fillRect(0,0,560,270);g.strokeStyle='#46616e';g.beginPath();g.moveTo(45,15);g.lineTo(45,235);g.lineTo(545,235);g.stroke();g.font='11px system-ui';g.fillStyle='#bad0d8';g.fillText('功率 %',6,15);g.fillText('距离 m →',460,260);for(let i=0;i<=4;i++){g.fillText(String(i*250),40+i*123,250)}g.strokeStyle='#96e2ed';g.beginPath();g.moveTo(45,235-s.b*215);g.lineTo(535,235-(s.w+s.b)*215);g.stroke();for(const p of s.rows){g.fillStyle='#e9bd86';g.beginPath();g.arc(45+p.x*490,235-p.y*215,5,0,7);g.fill()}const m=document.getElementById('cal-metrics');if(m)m.textContent=`w ${s.w.toFixed(3)} · b ${s.b.toFixed(3)} · 试射记录 ${s.rows.length}/4 · MSE ${loss(s)===null?'—':loss(s).toFixed(5)} · 更新 ${s.steps} 次`}
 function overlay(g,s,u,c,w,h,project,now){if(!s.active&&!s.unlocked)return;const ground=ExoWorld.elevation(c.x,c.y),p=(x,y,z=10)=>project(x,y,ExoWorld.elevation(x,y)+z-ground,c,w,h);if(s.active){for(const station of stations){const a=p(station.x,station.y);if(a.d<100||a.d>1900)continue;g.strokeStyle=station.test?'#ffc18a':'#93e4e5';g.beginPath();g.ellipse(a.x,a.y,55*a.s,16*a.s,0,0,7);g.stroke();g.fillStyle=g.strokeStyle;g.font='12px system-ui';g.textAlign='center';g.fillText(station.name+' / '+station.distance*1000+'m',a.x,a.y-12)}}if(s.beam&&s.beam.t>0){const a=p(s.beam.from.x,s.beam.from.y,65),b=p(s.beam.to.x,s.beam.to.y,80);g.strokeStyle=Math.abs(s.beam.error)<.035?'#a7f1db':'#f5ad84';g.lineWidth=3;g.beginPath();g.moveTo(a.x,a.y);g.lineTo(b.x,b.y);g.stroke()}if(s.unlocked&&s.autoAim&&!s.active){const d=Math.hypot(u.x-tower.x,u.y-tower.y)/1000;if(d<=1.1){const a=p(u.x,u.y,65),b=p(tower.x,tower.y,80);g.setLineDash([5,7]);g.strokeStyle='#8de1e7';g.lineWidth=1;g.beginPath();g.moveTo(a.x,a.y);g.lineTo(b.x,b.y);g.stroke();g.setLineDash([]);g.fillStyle='#b5eced';g.fillText('预测功率 '+((s.w*d+s.b)*100).toFixed(1)+'%',a.x,a.y-15)}}}
 return {tower,stations,fresh,loss,nearest,set,shoot,train,save,restore,panel,chart,overlay};
})();
if(typeof module!=='undefined')module.exports=ExoCalibration;
